const sourceCode = "import { Cards } from 'nextra/components'\nimport {BoxCard} from '../../components/BoxCard'\nimport Link from 'next/link'\n\n# Boxicons React Package\n\nReact icon library built from Boxicons SVG files with full tree-shaking support.\nThere are two versions available: Free and Pro.\nFree version includes basic and filled icon packs (1 style & weight), while Pro unlocks all icon packs, styles, and weights. Both include brands pack.\nThey can be installed with two commands and used in the similar way.\n\nThe Icon Components are Tree-shakable, so only the icons you import will be included in your final bundle.\n<br/>\n\n---\n<br/>\n<Cards >\n<BoxCard\n    icon={<i className=\"bxdocs bx-react bx-md absolute right-5 top-5 opacity-50\" />}\n    title=\"Free Package\"\n    href=\"/react/free/install\"\n    description=\"Use basic and filled icon packs with the free version of Boxicons React package.\"\n  /><BoxCard\n    icon={<i className=\"bxdocs bx-react bx-md absolute right-5 top-5 opacity-50\" />}\n    title=\"Pro Package\"\n    href=\"/react/pro/install\"\n    description=\"Use all icon packs, styles, and weights with the Pro version of Boxicons React package. \"\n  />\n</Cards>";
